    const last = () => cmds.filter(c => c[0] !== 'styleWithCSS').pop(); for (const [label, cmd] of [['Bold', 'bold'], ['Italic', 'italic'], ['Underline', 'underline'], ['Strikethrough', 'strikeThrough'], ['Bulleted list', 'insertUnorderedList'], ['Numbered list', 'insertOrderedList'], ['Clear formatting', 'removeFormat']]) { await h.click(tb.querySelector(`[aria-label="${label}"]`)); assert.strictEqual(last()[0], cmd, label); }
