    await h.click(tb.querySelector('[aria-label="Highlight"]')); await h.click(document.querySelector('.lb-swatchpop [aria-label="Highlight #fefcbf"]')); assert.deepStrictEqual(last(), ['hiliteColor', '#fefcbf']); await h.click(tb.querySelector('[aria-label="Highlight"]')); await h.click(document.querySelector('.lb-swatchpop [aria-label="No highlight"]')); assert.deepStrictEqual(last(), ['hiliteColor', 'transparent']);
