    await put('<div>Please <b>bring</b> <span style="color: rgb(229, 62, 62)">red</span> towels</div><ul><li>one</li><li><i>two</i></li></ul><div>&lt;script&gt;alert(1)&lt;/script&gt;</div>'); assert(!ed.classList.contains('is-empty')); assert(/\d+ \/ 4000/.test(h.el.querySelector('.lb-form .lb-flabel small').textContent));
    await h.type(field(h, 'Title'), 'Towels'); await h.click(h.btn(/^Housekeeping$/) || h.el); await h.click(h.el.querySelector('.lb-form [aria-label="Intended for"] button:first-child')); await h.click(h.btn(/^Publish note/)); const post = calls.find(c => c.method === 'POST' && /\/logbook\/notes$/.test(c.p)); assert(post, 'sent: ' + calls.map(c => c.method + c.p).join(' '));
    assert.deepStrictEqual(post.body.bodyRich.lines.map(l => l.k), ['p', 'ul', 'ul', 'p']); assert.deepStrictEqual(post.body.bodyRich.lines[0].runs, [{ t: 'Please ' }, { t: 'bring', b: true }, { t: ' ' }, { t: 'red', c: '#e53e3e' }, { t: ' towels' }]); assert.deepStrictEqual(post.body.bodyRich.lines[2].runs, [{ t: 'two', i: true }]); assert.strictEqual(post.body.body, undefined, 'only the document is sent — the server derives the plain text');
    const card = h.el.querySelector('[data-note^="new"]'); assert(card.querySelector('.lb-rich strong').textContent === 'bring' && card.querySelector('.lb-rich span[style*="color"]').textContent === 'red' && card.querySelectorAll('.lb-rich ul li').length === 2 && card.querySelector('.lb-rich em').textContent === 'two', 'drawn with React elements'); assert.strictEqual(card.querySelector('script'), null); assert(/<script>alert\(1\)<\/script>/.test(card.querySelector('.lb-rich').textContent), 'markup typed as text is shown as text');
    await h.click(h.btn(/^Edit Towels/)); const ed2 = field(h, 'Description'); assert(ed2.querySelector('b') && ed2.querySelector('ul li i') && ed2.querySelector('span[style*="color"]'), 'the editor opens with the formatting'); assert.strictEqual(ed2.querySelector('script'), null);
    cmds.length = 0; let prevented = false; await act(async () => { const e = new w.Event('paste', { bubbles: true, cancelable: true }); e.clipboardData = { getData: (t) => (t === 'text/plain' ? 'plain pasted' : '<b>rich</b>') }; ed2.dispatchEvent(e); prevented = e.defaultPrevented; }); assert(prevented, 'the browser\'s own paste is cancelled'); assert.deepStrictEqual(cmds.find(c => c[0] === 'insertText'), ['insertText', 'plain pasted'], 'pasted text goes in as plain text');
